<?php
declare(strict_types=1);
final class SearchService { private function cut(string $s,int $n):string{return function_exists('mb_substr')?mb_substr($s,0,$n):substr($s,0,$n);} public function __construct(private readonly WorkspaceService $ws,private readonly array $config){} public function search(array $a):array{$term=trim((string)($a['termo']??$a['term']??''));$name=trim((string)($a['nome']??$a['name']??''));$path=(string)($a['caminho']??$a['path']??'arquivos');$ext=ltrim(strtolower(trim((string)($a['extensao']??$a['extension']??''))),'.');$mode=(string)($a['modo']??$a['mode']??'content');$limit=min(200,max(1,(int)($a['limite']??$a['limit']??100)));if($term===''&&$name==='')throw new InvalidArgumentException('Informe termo ou nome para pesquisar.');$base=$this->ws->safe($path,true);if(!is_dir($base))$base=dirname($base);$root=$this->ws->root();$hits=[];$scanned=0;$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($base,FilesystemIterator::SKIP_DOTS));foreach($it as $f){if(count($hits)>=$limit||$scanned++>=2000)break;if(!$f->isFile()||is_link($f->getPathname()))continue;$filename=$f->getFilename();if($name!==''&&stripos($filename,$name)===false)continue;if($ext!==''&&strtolower($f->getExtension())!==$ext)continue;$rel=str_replace('\\','/',substr($f->getPathname(),strlen($root)+1));try{$this->ws->safe($rel,true);}catch(Throwable){continue;}$hit=['caminho'=>$rel,'nome'=>$filename,'extensao'=>strtolower($f->getExtension()),'tamanho'=>$f->getSize(),'modificado'=>date('c',$f->getMTime())];if($term!==''&&in_array($mode,['content','both'],true)){if($f->getSize()>($this->config['limits']['max_search_file_bytes']??524288))continue;$data=@file_get_contents($f->getPathname());if($data===false||str_contains(substr($data,0,4096),"\0"))continue;$lines=preg_split('/\R/',$data);foreach($lines as $i=>$line){if(stripos($line,$term)!==false){$hit['linha']=$i+1;$hit['trecho']=$this->cut(trim($line),500);$hits[]=$hit;break;}}}elseif($term!==''&&$mode==='name'){$hits[]=$hit;}else{$hits[]=$hit;}}return ['ok'=>true,'termo'=>$term,'nome'=>$name,'pasta'=>$path,'extensao'=>$ext,'modo'=>$mode,'resultados'=>$hits,'total'=>count($hits),'limitado'=>count($hits)>=$limit||$scanned>=2000];} }
